// Own: zzOWN.com - Own Fast. Work Faster.  | Ema: zzown.com@gmail.com
// Des: Tests for cf-site-rule: layers, wildcards, list adds, caps, refusals
// Flo: JSON configs > siteConf / siteChek / siteExpl > assert outp values, sources, error text
// I/O: inline config text > pass or fail (no leaks)
// Run: zig build test
// ===================================================================
const std = @import("std"); const site = @import("cf-site-rule.zig"); const cfgz = @import("cf-conf-load.zig");
const allo = std.testing.allocator;
const BASE = "{\"rate_host_seco\":1,\"fetc_body_maxz\":1000,\"capz_cred_pagz\":0,\"grup_rule_mapz\":{\"retail\":{\"rate_host_seco\":5,\"geoz_code_dflt\":\"us\",\"cons_sele_list\":[\"#a\"]}},\"site_rule_list\":[{\"name\":\"shop\",\"host\":[\"shop.com\",\"*.shop.com\"],\"grup\":\"retail\",\"rate_host_seco\":7,\"cons_sele_list_adds\":[\"#b\"],\"path_rule_list\":[{\"path\":\"/api/*\",\"rate_host_seco\":9,\"brow_enab\":true}]},{\"name\":\"deep\",\"host\":[\"deep.shop.com\"],\"rate_host_seco\":3},{\"name\":\"off\",\"host\":[\"off.com\"],\"enab\":false,\"rate_host_seco\":99}]}";
fn load(aren: std.mem.Allocator, text: []const u8) !cfgz.Conf { return cfgz.confPars(aren, text); }
fn chek(text: []const u8) ![]const u8 { var aren = std.heap.ArenaAllocator.init(allo); defer aren.deinit(); const conf = try load(aren.allocator(), text); var diag: site.Diag = .{}; site.siteChek(conf, &diag) catch return diag.text; return ""; }
test "layers: global, then group, then site, then path rule" { var aren = std.heap.ArenaAllocator.init(allo); defer aren.deinit(); const conf = try load(aren.allocator(), BASE); const bare = try site.siteConf(aren.allocator(), conf, "other.com", "/"); try std.testing.expectEqual(@as(u32, 1), bare.rate_host_seco); const shop = try site.siteConf(aren.allocator(), conf, "shop.com", "/x"); try std.testing.expectEqual(@as(u32, 7), shop.rate_host_seco); try std.testing.expectEqualStrings("us", shop.geoz_code_dflt); try std.testing.expect(!shop.brow_enab); const apiz = try site.siteConf(aren.allocator(), conf, "shop.com", "/api/items"); try std.testing.expectEqual(@as(u32, 9), apiz.rate_host_seco); try std.testing.expect(apiz.brow_enab); }
test "wildcard matches subdomains only, exact host beats wildcard" { var aren = std.heap.ArenaAllocator.init(allo); defer aren.deinit(); const conf = try load(aren.allocator(), BASE); const subz = try site.siteConf(aren.allocator(), conf, "a.shop.com", "/"); try std.testing.expectEqual(@as(u32, 7), subz.rate_host_seco); const deep = try site.siteConf(aren.allocator(), conf, "deep.shop.com", "/"); try std.testing.expectEqual(@as(u32, 3), deep.rate_host_seco); try std.testing.expect(site.hostMach("*.shop.com", "shop.com") < 0); try std.testing.expect(site.hostMach("*.shop.com", "xshop.com") < 0); try std.testing.expect(site.hostMach("Shop.COM", "shop.com") > 0); }
test "list keys: bare replaces, _adds appends" { var aren = std.heap.ArenaAllocator.init(allo); defer aren.deinit(); const conf = try load(aren.allocator(), BASE); const shop = try site.siteConf(aren.allocator(), conf, "shop.com", "/"); try std.testing.expectEqual(@as(usize, 2), shop.cons_sele_list.len); try std.testing.expectEqualStrings("#a", shop.cons_sele_list[0]); try std.testing.expectEqualStrings("#b", shop.cons_sele_list[1]); try std.testing.expect(conf.cons_sele_list.len > 2); }
test "disabled rule is ignored, merge is idempotent on the base config" { var aren = std.heap.ArenaAllocator.init(allo); defer aren.deinit(); const conf = try load(aren.allocator(), BASE); const offz = try site.siteConf(aren.allocator(), conf, "off.com", "/"); try std.testing.expectEqual(@as(u32, 1), offz.rate_host_seco); const onez = try site.siteConf(aren.allocator(), conf, "shop.com", "/"); const twoz = try site.siteConf(aren.allocator(), conf, "shop.com", "/"); try std.testing.expectEqual(onez.cons_sele_list.len, twoz.cons_sele_list.len); }
test "explain: each changed key shows the layer it came from" { var aren = std.heap.ArenaAllocator.init(allo); defer aren.deinit(); const conf = try load(aren.allocator(), BASE); var srcs: std.ArrayList(site.Srcz) = .empty; const outp = try site.siteExpl(aren.allocator(), conf, "shop.com", "/api/x", &srcs); try std.testing.expectEqual(@as(u32, 9), outp.rate_host_seco); var from: []const u8 = ""; for (srcs.items) |item| { if (std.mem.eql(u8, item.keyz, "brow_enab")) from = item.from; } try std.testing.expectEqualStrings("path /api/*", from); try std.testing.expectEqualStrings("9", try site.valuText(aren.allocator(), outp, "rate_host_seco")); }
test "a valid file passes the check" { try std.testing.expectEqualStrings("", try chek(BASE)); try std.testing.expectEqualStrings("", try chek("{}")); }
test "a rule can only lower caps, never raise them" { try std.testing.expect(std.mem.indexOf(u8, try chek("{\"fetc_body_maxz\":1000,\"site_rule_list\":[{\"name\":\"a\",\"host\":[\"a.com\"],\"fetc_body_maxz\":5000}]}"), "fetc_body_maxz") != null); try std.testing.expectEqualStrings("", try chek("{\"fetc_body_maxz\":1000,\"site_rule_list\":[{\"name\":\"a\",\"host\":[\"a.com\"],\"fetc_body_maxz\":500}]}")); try std.testing.expect(std.mem.indexOf(u8, try chek("{\"capz_cred_pagz\":5,\"site_rule_list\":[{\"name\":\"a\",\"host\":[\"a.com\"],\"capz_cred_pagz\":0}]}"), "capz_cred_pagz") != null); try std.testing.expectEqualStrings("", try chek("{\"capz_cred_pagz\":0,\"site_rule_list\":[{\"name\":\"a\",\"host\":[\"a.com\"],\"capz_cred_pagz\":3}]}")); }
test "forbidden and unknown keys are refused with the key name" { try std.testing.expect(std.mem.indexOf(u8, try chek("{\"site_rule_list\":[{\"name\":\"a\",\"host\":[\"a.com\"],\"uagt_cont_mail\":\"x@y.z\"}]}"), "uagt_cont_mail") != null); try std.testing.expect(std.mem.indexOf(u8, try chek("{\"site_rule_list\":[{\"name\":\"a\",\"host\":[\"a.com\"],\"vend_free_cred\":{\"deco\":5}}]}"), "vend_free_cred") != null); try std.testing.expect(std.mem.indexOf(u8, try chek("{\"site_rule_list\":[{\"name\":\"a\",\"host\":[\"a.com\"],\"nope_nope_nope\":1}]}"), "nope_nope_nope") != null); try std.testing.expect(std.mem.indexOf(u8, try chek("{\"site_rule_list\":[{\"name\":\"a\",\"host\":[\"a.com\"],\"rate_host_seco_adds\":[1]}]}"), "rate_host_seco") != null); }
test "bad shapes: type, group, name, host, tier, status codes" { try std.testing.expect(std.mem.indexOf(u8, try chek("{\"site_rule_list\":[{\"name\":\"a\",\"host\":[\"a.com\"],\"rate_host_seco\":\"fast\"}]}"), "wrong type") != null); try std.testing.expect(std.mem.indexOf(u8, try chek("{\"site_rule_list\":[{\"name\":\"a\",\"host\":[\"a.com\"],\"grup\":\"ghost\"}]}"), "ghost") != null); try std.testing.expect(std.mem.indexOf(u8, try chek("{\"site_rule_list\":[{\"name\":\"a\",\"host\":[\"a.com\"]},{\"name\":\"a\",\"host\":[\"b.com\"]}]}"), "twice") != null); try std.testing.expect(std.mem.indexOf(u8, try chek("{\"site_rule_list\":[{\"name\":\"a\",\"host\":[\"a.*.com\"]}]}"), "host pattern") != null); try std.testing.expect(std.mem.indexOf(u8, try chek("{\"site_rule_list\":[{\"name\":\"a\",\"host\":[\"a.com/x\"]}]}"), "host pattern") != null); try std.testing.expect(std.mem.indexOf(u8, try chek("{\"site_rule_list\":[{\"name\":\"a\",\"host\":[\"a.com\"],\"tier_star\":\"turbo\"}]}"), "tier_star") != null); try std.testing.expect(std.mem.indexOf(u8, try chek("{\"site_rule_list\":[{\"name\":\"a\",\"host\":[\"a.com\"],\"retr_code_list\":[99]}]}"), "retr_code_list") != null); try std.testing.expect(std.mem.indexOf(u8, try chek("{\"site_rule_list\":[{\"name\":\"a\",\"host\":[\"a.com\"],\"vend_bann_list\":[\"nobody\"]}]}"), "vend_bann_list") != null); try std.testing.expect(std.mem.indexOf(u8, try chek("{\"site_rule_list\":[{\"host\":[\"a.com\"]}]}"), "no name") != null); try std.testing.expect(std.mem.indexOf(u8, try chek("{\"site_rule_list\":[{\"name\":\"a\",\"host\":[\"a.com\"],\"path_rule_list\":[{\"rate_host_seco\":2}]}]}"), "no path") != null); }
test "a bad group is caught even if no site uses it" { try std.testing.expect(std.mem.indexOf(u8, try chek("{\"grup_rule_mapz\":{\"g\":{\"geoz_code_dflt\":\"usa\"}}}"), "group g") != null); }
test "glob: star, question mark, anchors" { try std.testing.expect(site.globMach("/api/*", "/api/a/b")); try std.testing.expect(!site.globMach("/api/*", "/apx/a")); try std.testing.expect(site.globMach("*.pdf", "/files/x.pdf")); try std.testing.expect(site.globMach("/p?", "/p1")); try std.testing.expect(!site.globMach("/p?", "/p12")); try std.testing.expect(site.globMach("*", "")); try std.testing.expect(site.globMach("/a*b*c", "/aXXbYYc")); try std.testing.expect(!site.globMach("/a*b*c", "/aXXbYY")); }
test "siteTrue finds a browser switch anywhere in the rules" { var aren = std.heap.ArenaAllocator.init(allo); defer aren.deinit(); const conf = try load(aren.allocator(), BASE); try std.testing.expect(site.siteTrue(conf, "brow_enab")); const none = try load(aren.allocator(), "{\"site_rule_list\":[{\"name\":\"a\",\"host\":[\"a.com\"],\"rate_host_seco\":2}]}"); try std.testing.expect(!site.siteTrue(none, "brow_enab")); }
